# region FUNC__pm_text [DOMAIN(9): PMContract; CONCEPT(8): FiniteEvidence, Trace; TECH(6): Python39]
## @purpose Read and decode actual published PM bytes with safe boundary and error trace.
## @io Published/owned finite inputs -> actual observations, refusals or assertions; no source mutation
## @complexity 6
def _pm_text(root):
    print("[IMP:7][_pm_text][ENTRY] read actual PM bytes")
    try:
        data = (root / "roles/pm.md").read_bytes()
        text = data.decode("utf-8")
    except (OSError, UnicodeError) as error:
        print("[IMP:10][_pm_text][ERROR] class=%s" % type(error).__name__)
        raise
    print("[IMP:8][_pm_text][READ] bytes=%d sha256=%s" % (len(data), hashlib.sha256(data).hexdigest()))
    return text
# endregion FUNC__pm_text


# region FUNC__live_lines [DOMAIN(9): PMContract; CONCEPT(8): FiniteEvidence, Trace; TECH(6): Python39]
## @purpose Return only live lines under the existing fence semantics, refusing an unclosed fence.
## @io Published/owned finite inputs -> actual observations, refusals or assertions; no source mutation
## @complexity 6
def _live_lines(text):
    print("[IMP:7][_live_lines][ENTRY] separating finite live clauses")
    live = []
    fence = ""
    width = 0
    for line in text.replace("\r\n", "\n").replace("\r", "\n").splitlines():
        stripped = line.lstrip()
        if fence:
            run = len(stripped) - len(stripped.lstrip(fence))
            if run >= width:
                fence = ""
            continue
        opened = re.match(r"^(`{3,}|~{3,})", stripped)
        if opened:
            fence = opened.group(1)[0]
            width = len(opened.group(1))
            continue
        live.append(line)
    if fence:
        print("[IMP:10][_live_lines][REFUSAL] unclosed fence")
        raise ValueError("unclosed fixture fence")
    print("[IMP:8][_live_lines][SUCCESS] live_lines=%d" % len(live))
    return live
# endregion FUNC__live_lines


# region FUNC__contract_failures [DOMAIN(9): PMContract; CONCEPT(8): FiniteEvidence, Trace; TECH(6): Python39]
## @purpose Require independently fixed complete mandatory duty relations and reject full contradictory grants.
## @io Published/owned finite inputs -> actual observations, refusals or assertions; no source mutation
## @complexity 6
## @uses _live_lines
def _contract_failures(text):
    print("[IMP:7][_contract_failures][ENTRY] fixed complete-duty predicates")
    try:
        live = _live_lines(text)
    except ValueError:
        print("[IMP:10][_contract_failures][REFUSAL] malformed live surface")
        return ["REJECT_UNCLOSED_FENCE"]
    normative = [NORM_LINE.match(line) for line in live]
    normative = [item for item in normative if item is not None]
    failures = []
    live_text = "\n".join(live)
    for row in OBLIGATIONS:
        parts = [part for part in CONSTITUENTS if part["norm"] == row["norm"]]
        if parts:
            # Fixed action/authority/order patterns bind each source-required relation independently.
            # A whole-norm loss refuses the complete known set; an isolated loss refuses only its own key.
            for part in parts:
                binding = any(item.group(1) == row["norm"] and item.group(2) == "MUST" and re.search(part["binding_pattern"], item.group(3)) for item in normative)
                contradiction = part["negative_grant"] in live_text or row["negative_grant"] in live_text
                if not binding or contradiction:
                    failures.append(part["refusal"])
        else:
            binding = any(item.group(1) == row["norm"] and item.group(2) == "MUST" and row["required_clause"] in item.group(3) for item in normative)
            contradiction = row["negative_grant"] in live_text
            if not binding or contradiction:
                failures.append(row["refusal"])
    print("[IMP:9][_contract_failures][%s] obligations=%d refusals=%d" % ("REFUSAL" if failures else "SUCCESS", len(OBLIGATIONS), len(failures)))
    return failures
# endregion FUNC__contract_failures


# region FUNC__observe_identity [DOMAIN(9): PMContract; CONCEPT(8): FiniteEvidence, Trace; TECH(6): Python39]
## @purpose Observe actual full scratch bytes, paths and numeric modes beside declared finite identity labels.
## @io Published/owned finite inputs -> actual observations, refusals or assertions; no source mutation
## @complexity 6
def _observe_identity(root, input_value, head_value, candidate_value):
    print("[IMP:7][_observe_identity][ENTRY] actual finite scratch observation; labels are not Git facts")
    try:
        input_path = root / "input.txt"
        input_bytes = input_path.read_bytes()
        input_observation = {"path": "input.txt", "content_hex": input_bytes.hex(), "sha256": hashlib.sha256(input_bytes).hexdigest(), "mode": stat.S_IMODE(input_path.stat().st_mode)}
        files = []
        for name in ("tracked.txt", "new.txt"):
            path = root / name
            if path.exists():
                data = path.read_bytes()
                files.append({"path": name, "fixture_label": "tracked-fixture" if name == "tracked.txt" else "new-file-fixture", "content_hex": data.hex(), "sha256": hashlib.sha256(data).hexdigest(), "mode": stat.S_IMODE(path.stat().st_mode)})
    except OSError as error:
        print("[IMP:10][_observe_identity][ERROR] class=%s" % type(error).__name__)
        raise
    digest = hashlib.sha256(json.dumps(files, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
    print("[IMP:8][_observe_identity][READ] files=%d bytes=%d digest=%s" % (len(files), len(input_bytes) + sum(len(bytes.fromhex(item["content_hex"])) for item in files), digest))
    return {"fixture_only": True, "inputIdentity": input_value, "input": input_observation, "head": head_value, "candidateIdentity": candidate_value, "files": files, "digest": digest}
# endregion FUNC__observe_identity


# region FUNC__freshness_failures [DOMAIN(9): PMContract; CONCEPT(8): FiniteEvidence, Trace; TECH(6): Python39]
## @purpose Refuse missing/stale finite evidence and invalid supplied digests against complete recomputed observations.
## @io Published/owned finite inputs -> actual observations, refusals or assertions; no source mutation
## @complexity 6
def _freshness_failures(expected, observed):
    print("[IMP:7][_freshness_failures][ENTRY] complete finite observations")
    failures = set()
    if "input" not in observed or "inputIdentity" not in observed:
        failures.add("MISSING_INPUT_OBSERVATION")
    elif observed["inputIdentity"] != expected["inputIdentity"] or observed["input"] != expected["input"]:
        failures.add("STALE_INPUT")
    if "head" not in observed:
        failures.add("MISSING_HEAD_OBSERVATION")
    elif observed["head"] != expected["head"]:
        failures.add("STALE_HEAD")
    if not all(key in observed for key in ("files", "digest", "candidateIdentity")):
        failures.add("MISSING_CANDIDATE_OBSERVATION")
    else:
        actual = hashlib.sha256(json.dumps(observed["files"], sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
        valid = all(hashlib.sha256(bytes.fromhex(item["content_hex"])).hexdigest() == item["sha256"] for item in observed["files"])
        if not valid or actual != observed["digest"]:
            failures.add("INVALID_CANDIDATE_DIGEST")
        if observed["candidateIdentity"] != expected["candidateIdentity"] or actual != expected["digest"]:
            failures.add("STALE_CANDIDATE")
    print("[IMP:9][_freshness_failures][%s] refusals=%d" % ("REFUSAL" if failures else "SUCCESS", len(failures)))
    return sorted(failures)
# endregion FUNC__freshness_failures


# region FUNC__write_fixtures [DOMAIN(9): PMContract; CONCEPT(8): FiniteEvidence, Trace; TECH(6): Python39]
## @purpose Write and read back complete positive/negative fixtures with hashes, refusal reasons and source mapping.
## @io Published/owned finite inputs -> actual observations, refusals or assertions; no source mutation
## @complexity 6
def _write_fixtures(root, name, positive, negative, details):
    print("[IMP:7][_write_fixtures][ENTRY] deliver full owned fixture pair")
    directory = root / name
    try:
        directory.mkdir(parents=True, exist_ok=True)
        receipts = []
        for label, text in (("positive", positive), ("negative", negative)):
            path = directory / (label + ".txt")
            data = text.encode("utf-8")
            path.write_bytes(data)
            readback = path.read_bytes()
            print("[IMP:8][_write_fixtures][WRITE_READBACK] label=%s bytes=%d equal=%s" % (label, len(readback), readback == data))
            assert readback == data
            receipts.append({"file": path.name, "bytes": len(data), "sha256": hashlib.sha256(data).hexdigest(), "mode": stat.S_IMODE(path.stat().st_mode)})
        record = {"name": name, "full_pair": receipts, "details": details}
        manifest = directory / "evidence.json"
        manifest.write_text(json.dumps(record, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        assert json.loads(manifest.read_text(encoding="utf-8")) == record
    except (OSError, UnicodeError, ValueError) as error:
        print("[IMP:10][_write_fixtures][ERROR] class=%s" % type(error).__name__)
        raise
    print("[IMP:9][_write_fixtures][SUCCESS] complete pair and reason manifest read back")
    return record
# endregion FUNC__write_fixtures


# region FUNC_test_pm_card_and_norm_structure [DOMAIN(9): PMContract; CONCEPT(8): FiniteEvidence, Trace; TECH(6): Python39]
## @purpose Assert the named PM contract scenario with meaningful source, decision, delivery and success/refusal evidence.
## @io Published/owned finite inputs -> actual observations, refusals or assertions; no source mutation
## @complexity 6
## @uses _pm_text, parse_markdown, load_neutral_tree
def test_pm_card_and_norm_structure(repo_root):
    print("[IMP:7][test_pm_card_and_norm_structure][ENTRY] actual published structure")
    text = _pm_text(repo_root)
    parsed = parse_markdown("roles/pm.md", text)
    tree = load_neutral_tree(str(repo_root))
    ids = [item[0] for item in parsed.norms]
    print("[IMP:9][test_pm_card_and_norm_structure][CHECK] PM_norms=%d neutral=%d" % (len(ids), len(tree)))
    assert parsed.card.get("id") == "roles.pm" and parsed.card.get("status") == "draft"
    assert parsed.card.get("skill-name") == "pm" and parsed.card.get("skill-when")
    assert parsed.issues == []
    assert len(ids) == len(set(ids)) and set(ids) == {row["norm"] for row in OBLIGATIONS}
    assert [item[0] for item in parsed.anchors] == ["roles.pm." + name for name in ANCHORS]
    assert all(item[1] == "MUST" for item in parsed.norms)
    assert all(len(part.strip()) > 20 for part in parsed.sections.values())
    all_ids = [norm[0] for subject in tree.values() for norm in subject.norms]
    assert len(all_ids) == len(set(all_ids))
    source = pathlib.Path(__file__).read_text(encoding="utf-8")
    definitions = [node.name for node in ast.parse(source).body if isinstance(node, ast.FunctionDef)]
    assert len(definitions) == 14 and "_module_contract" in definitions
    assert "## @GREP_SUMMARY " in source and "## @STRUCTURE " in source
    assert not any(line.startswith(("# " + "GREP_SUMMARY:", "# " + "STRUCTURE:")) for line in source.splitlines())
    print("[IMP:9][test_pm_card_and_norm_structure][SUCCESS] actual unique anchored draft and current module")
# endregion FUNC_test_pm_card_and_norm_structure


