# region FUNC_test_pm_finite_weakened_fixtures [DOMAIN(9): PMContract; CONCEPT(8): FiniteEvidence, Trace; TECH(6): Python39]
## @purpose Assert the named PM contract scenario with meaningful source, decision, delivery and success/refusal evidence.
## @io Published/owned finite inputs -> actual observations, refusals or assertions; no source mutation
## @complexity 6
## @uses _contract_failures, _write_fixtures
def test_pm_finite_weakened_fixtures(tmp_path):
    print("[IMP:7][test_pm_finite_weakened_fixtures][ENTRY] independent complete finite fixture corpus")
    assert {row["family"] for row in OBLIGATIONS} == set(FAMILIES) and len(FAMILIES) == 12
    assert len({row["key"] for row in OBLIGATIONS}) == len(OBLIGATIONS)
    assert _contract_failures(FIXED_POSITIVE) == []
    for index, row in enumerate(OBLIGATIONS):
        original = "- **%s** MUST: %s" % (row["norm"], row["required_clause"])
        weakened = FIXED_POSITIVE.replace(original, "- **%s** MAY: %s" % (row["norm"], row["required_clause"]), 1)
        contradictory = FIXED_POSITIVE + "\n- **CONTROL-%d** MAY: %s\n" % (index + 1, row["negative_grant"])
        assert weakened != FIXED_POSITIVE and contradictory != FIXED_POSITIVE
        for kind, negative in (("optionalized", weakened), ("contradictory-grant", contradictory)):
            actual = _contract_failures(negative)
            expected = [part["refusal"] for part in CONSTITUENTS if part["norm"] == row["norm"]] or [row["refusal"]]
            print("[IMP:9][test_pm_finite_weakened_fixtures][REFUSAL] family=%s key=%s kind=%s exact=%s" % (row["family"], row["key"], kind, actual == expected))
            _write_fixtures(tmp_path, "%03d-%s" % (index, kind), FIXED_POSITIVE, negative, {"source_mapping": row, "positive_expected": [], "positive_actual": [], "negative_expected": expected, "negative_actual": actual, "mutation": kind, "independent_semantic_judgment": False})
            assert actual == expected
    fenced = FIXED_POSITIVE + "\n```text\n" + OBLIGATIONS[0]["negative_grant"] + "\n```\n"
    assert _contract_failures(fenced) == []
    malformed = FIXED_POSITIVE + "\n```text\n"
    assert _contract_failures(malformed) == ["REJECT_UNCLOSED_FENCE"]
    _write_fixtures(tmp_path, "fence-controls", fenced, malformed, {"reason": "Fenced examples cannot supply or contradict live duties; an unclosed fence refuses the complete surface.", "negative_expected": ["REJECT_UNCLOSED_FENCE"], "negative_actual": _contract_failures(malformed)})
    print("[IMP:9][test_pm_finite_weakened_fixtures][SUCCESS] every constituent own negative and grant checked")
# endregion FUNC_test_pm_finite_weakened_fixtures


# region FUNC_test_pm_isolated_compound_constituents [DOMAIN(9): PMContract; CONCEPT(10): IndependentConstituent, OwnLoss, Restoration; TECH(6): Python39]
## @purpose Refuse each fixed independent compound duty loss alone while preserving all counterparts and unrelated obligations.
## @io Fixed source/spec clauses and singleton intentions -> full isolated fixtures, refusals and exact restoration proof
## @complexity 8
## @uses _contract_failures, _write_fixtures, NORM_LINE
def test_pm_isolated_compound_constituents(tmp_path):
    print("[IMP:7][test_pm_isolated_compound_constituents][ENTRY] fixed independently required own losses")
    assert _contract_failures(FIXED_POSITIVE) == []
    original_rows = {match.group(1): (match.group(2), match.group(3)) for line in FIXED_POSITIVE.splitlines() for match in [NORM_LINE.match(line)] if match}
    assert len({part["key"] for part in CONSTITUENTS}) == len(CONSTITUENTS)
    for part in CONSTITUENTS:
        row = next(item for item in OBLIGATIONS if item["norm"] == part["norm"])
        original = "- **%s** MUST: %s" % (row["norm"], row["required_clause"])
        trigger_count = row["required_clause"].count(part["loss_trigger"])
        assert trigger_count == 1 and FIXED_POSITIVE.count(original) == 1
        changed_clause = row["required_clause"].replace(part["loss_trigger"], part["loss_replacement"], 1)
        changed = "- **%s** MUST: %s" % (row["norm"], changed_clause)
        omitted = FIXED_POSITIVE.replace(original, changed, 1)
        grant = "\n- **CONTROL-OWN** MAY: %s\n" % part["negative_grant"]
        contradictory = FIXED_POSITIVE + grant
        expected = [part["refusal"]]
        for kind, negative in (("own-omission", omitted), ("own-contradictory-grant", contradictory)):
            actual = _contract_failures(negative)
            remaining = {match.group(1): (match.group(2), match.group(3)) for line in negative.splitlines() for match in [NORM_LINE.match(line)] if match and match.group(1) in original_rows}
            unrelated = {key: value for key, value in remaining.items() if key != row["norm"]}
            assert unrelated == {key: value for key, value in original_rows.items() if key != row["norm"]}
            assert remaining[row["norm"]][0] == "MUST"
            counterpart_patterns = [other for other in CONSTITUENTS if other["norm"] == row["norm"] and other["key"] != part["key"]]
            assert all(re.search(other["binding_pattern"], remaining[row["norm"]][1]) for other in counterpart_patterns)
            restored = negative.replace(changed, original, 1) if kind == "own-omission" else negative[:-len(grant)]
            assert restored == FIXED_POSITIVE and _contract_failures(restored) == []
            print("[IMP:9][test_pm_isolated_compound_constituents][REFUSAL] key=%s kind=%s triggers=%d singleton=%s counterparts=%d restored=%s" % (part["key"], kind, trigger_count, actual == expected, len(counterpart_patterns), restored == FIXED_POSITIVE))
            _write_fixtures(tmp_path, part["key"] + "-" + kind, FIXED_POSITIVE, negative, {"source_mapping": part, "positive_expected": [], "positive_actual": [], "negative_expected": expected, "negative_actual": actual, "reason": part["reason"], "unique_trigger_count": trigger_count, "counterpart_keys_preserved": [other["key"] for other in counterpart_patterns], "unrelated_norms_unchanged": len(unrelated), "all_original_norms_present": set(remaining) == set(original_rows), "restored_sha256": hashlib.sha256(restored.encode("utf-8")).hexdigest(), "restoration_exact": restored == FIXED_POSITIVE, "mutation": kind, "independent_semantic_judgment": False})
            assert actual == expected
    print("[IMP:9][test_pm_isolated_compound_constituents][SUCCESS] every confirmed own-loss intention discriminates")
# endregion FUNC_test_pm_isolated_compound_constituents


# region FUNC_test_pm_identity_freshness_fixtures [DOMAIN(9): PMContract; CONCEPT(8): FiniteEvidence, Trace; TECH(6): Python39]
## @purpose Assert the named PM contract scenario with meaningful source, decision, delivery and success/refusal evidence.
## @io Published/owned finite inputs -> actual observations, refusals or assertions; no source mutation
## @complexity 6
## @uses _observe_identity, _freshness_failures, _write_fixtures
def test_pm_identity_freshness_fixtures(tmp_path):
    print("[IMP:7][test_pm_identity_freshness_fixtures][ENTRY] five physical finite observation pairs")
    cases = (("F01-stale-input", "STALE_INPUT"), ("F02-stale-head", "STALE_HEAD"), ("F03-stale-candidate", "STALE_CANDIDATE"), ("F04-same-head-tracked", "STALE_CANDIDATE"), ("F05-same-head-new", "STALE_CANDIDATE"))
    for name, refusal in cases:
        directory = tmp_path / name / "actual-files"
        directory.mkdir(parents=True)
        (directory / "input.txt").write_bytes(b"independent input A\n")
        (directory / "tracked.txt").write_bytes(b"tracked fixture A\n")
        if name.startswith("F05"):
            (directory / "new.txt").write_bytes(b"new fixture A\n")
        before = _observe_identity(directory, "INPUT-A", "HEAD-A", "CANDIDATE-A")
        assert _freshness_failures(before, before) == []
        input_value, head_value, candidate_value = "INPUT-A", "HEAD-A", "CANDIDATE-A"
        if name.startswith("F01"):
            (directory / "input.txt").write_bytes(b"independent input B\n")
            input_value = "INPUT-B"
        elif name.startswith("F02"):
            head_value = "HEAD-B"
        elif name.startswith("F03"):
            (directory / "tracked.txt").write_bytes(b"candidate fixture B\n")
            candidate_value = "CANDIDATE-B"
        elif name.startswith("F04"):
            (directory / "tracked.txt").write_bytes(b"same HEAD tracked fixture B\n")
        else:
            (directory / "new.txt").write_bytes(b"same HEAD new fixture B\n")
        after = _observe_identity(directory, input_value, head_value, candidate_value)
        actual = _freshness_failures(before, after)
        print("[IMP:9][test_pm_identity_freshness_fixtures][REFUSAL] observation=%s exact=%s" % (name, actual == [refusal]))
        _write_fixtures(tmp_path, name, json.dumps(before, indent=2), json.dumps(after, indent=2), {"reason": "Actual scratch content/modes plus declared fixture identity values; no live Git inference.", "positive_expected": [], "positive_actual": [], "negative_expected": [refusal], "negative_actual": actual, "clause_mapping": ["PM-206", "PM-801", "PM-812", "PM-902"], "all_full_bytes_in_hex": True})
        assert actual == [refusal]
        if name.startswith(("F03", "F04", "F05")):
            concealed = json.loads(json.dumps(after))
            concealed["digest"] = before["digest"]
            expected = ["INVALID_CANDIDATE_DIGEST", "STALE_CANDIDATE"]
            concealed_actual = _freshness_failures(before, concealed)
            _write_fixtures(tmp_path, name + "-concealed", json.dumps(before, indent=2), json.dumps(concealed, indent=2), {"reason": "Old supplied digest cannot hide observed current full file bytes/modes.", "negative_expected": expected, "negative_actual": concealed_actual, "clause_mapping": ["PM-801", "PM-812"]})
            assert concealed_actual == expected
        if name.startswith(("F04", "F05")):
            assert before["head"] == after["head"] and before["files"] != after["files"]
    print("[IMP:9][test_pm_identity_freshness_fixtures][SUCCESS] five actual observations and concealment controls")
# endregion FUNC_test_pm_identity_freshness_fixtures


# region FUNC_test_pm_required_evidence_and_optional_absence [DOMAIN(9): PMContract; CONCEPT(8): FiniteEvidence, Trace; TECH(6): Python39]
## @purpose Assert the named PM contract scenario with meaningful source, decision, delivery and success/refusal evidence.
## @io Published/owned finite inputs -> actual observations, refusals or assertions; no source mutation
## @complexity 6
## @uses _observe_identity, _freshness_failures, _contract_failures, _write_fixtures
def test_pm_required_evidence_and_optional_absence(tmp_path):
    print("[IMP:7][test_pm_required_evidence_and_optional_absence][ENTRY] missing required versus absent optional")
    directory = tmp_path / "observed-files"
    directory.mkdir()
    (directory / "input.txt").write_bytes(b"required input\n")
    (directory / "tracked.txt").write_bytes(b"current fixture\n")
    observed = _observe_identity(directory, "INPUT-A", "HEAD-A", "CANDIDATE-A")
    # Optional producer detail is never fabricated. Its absence does not remove any actual required observation.
    assert "optionalDetail" not in observed and _freshness_failures(observed, observed) == []
    for key, expected in (("input", "MISSING_INPUT_OBSERVATION"), ("head", "MISSING_HEAD_OBSERVATION"), ("files", "MISSING_CANDIDATE_OBSERVATION")):
        missing = json.loads(json.dumps(observed))
        del missing[key]
        actual = _freshness_failures(observed, missing)
        _write_fixtures(tmp_path, "missing-" + key, json.dumps(observed, indent=2), json.dumps(missing, indent=2), {"reason": "A missing required observation refuses; a genuinely absent optional detail is allowed.", "negative_expected": [expected], "negative_actual": actual, "clause_mapping": ["PM-804", "PM-904", "PM-905"]})
        assert actual == [expected]
    for key in ("REQUIRED_MISSING_BLOCKS", "ACTUAL_TRIGGERED_NA", "NO_ORDINARY_GOAL_MONITOR"):
        row = next(item for item in OBLIGATIONS if item["key"] == key)
        old = "- **%s** MUST: %s" % (row["norm"], row["required_clause"])
        negative = FIXED_POSITIVE.replace(old, "- **%s** MAY: %s" % (row["norm"], row["required_clause"]), 1)
        actual = _contract_failures(negative)
        _write_fixtures(tmp_path, key, FIXED_POSITIVE, negative, {"source_mapping": row, "reason": "Absent optional facts do not waive required evidence or grant an unsolicited goal.", "negative_expected": [row["refusal"]], "negative_actual": actual})
        assert actual == [row["refusal"]]
    print("[IMP:9][test_pm_required_evidence_and_optional_absence][SUCCESS] optional omission distinct from required refusal")
# endregion FUNC_test_pm_required_evidence_and_optional_absence


